CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027221048_InitialCreate') THEN
    CREATE TABLE "AuditLogs" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "UserId" integer,
        "Username" character varying(64),
        "Action" character varying(64) NOT NULL,
        "EntityType" character varying(64) NOT NULL,
        "EntityId" character varying(64),
        "Details" character varying(4000),
        "IpAddress" character varying(64),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027221048_InitialCreate') THEN
    CREATE TABLE "OrderTypes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Code" character varying(32) NOT NULL,
        "Name" character varying(100) NOT NULL,
        "IsActive" boolean NOT NULL,
        "SortOrder" integer NOT NULL,
        CONSTRAINT "PK_OrderTypes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
