DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027221048_InitialCreate') THEN
    CREATE TABLE "RentalContracts" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" character varying(200) NOT NULL,
        "PropertyType" character varying(20) NOT NULL,
        "Location" character varying(300),
        "BeneficiaryName" character varying(150) NOT NULL,
        "BeneficiaryPhone" character varying(32),
        "Amount" numeric(18,2) NOT NULL,
        "DueDate" date NOT NULL,
        "Notes" character varying(1000),
        "IsArchived" boolean NOT NULL,
        "LockVersion" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "CreatedByUserId" integer NOT NULL,
        CONSTRAINT "PK_RentalContracts" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_RentalContract_Amount" CHECK ("Amount" > 0)
    );
    END IF;
END $EF$;

