        "Description" character varying(500),
        "DefaultPrice" numeric(18,2),
        "OrderTypeId" integer,
        "IsActive" boolean NOT NULL,
        "SortOrder" integer NOT NULL,
        CONSTRAINT "PK_Services" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Service_DefaultPrice" CHECK ("DefaultPrice" IS NULL OR "DefaultPrice" > 0),
        CONSTRAINT "FK_Services_OrderTypes_OrderTypeId" FOREIGN KEY ("OrderTypeId") REFERENCES "OrderTypes" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027221048_InitialCreate') THEN
