        "RentalId" integer NOT NULL,
        "Amount" numeric(18,2) NOT NULL,
        "PaymentMethodId" integer NOT NULL,
        "PaidOn" date NOT NULL,
        "Reference" character varying(100),
        "Notes" character varying(500),
        "AttachmentStoredName" character varying(100),
        "AttachmentOriginalName" character varying(255),
        "AttachmentContentType" character varying(100),
        "IdempotencyKey" character varying(64),
        "IsVoided" boolean NOT NULL,
        "VoidReason" character varying(500),
        "VoidedAtUtc" timestamp with time zone,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "CreatedByUserId" integer NOT NULL,
        CONSTRAINT "PK_RentalPayments" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_RentalPayment_Amount" CHECK ("Amount" > 0),
        CONSTRAINT "FK_RentalPayments_PaymentMethods_PaymentMethodId" FOREIGN KEY ("PaymentMethodId") REFERENCES "PaymentMethods" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_RentalPayments_RentalContracts_RentalId" FOREIGN KEY ("RentalId") REFERENCES "RentalContracts" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

