        "EffectiveFromUtc" timestamp with time zone NOT NULL,
        "EffectiveToUtc" timestamp with time zone,
        "CreatedByUserId" integer,
        "Notes" character varying(500),
        CONSTRAINT "PK_EmployeeDeductionRates" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_DeductionRate_Percentage" CHECK ("Percentage" >= 0 AND "Percentage" <= 100),
        CONSTRAINT "FK_EmployeeDeductionRates_EmployeeProfiles_EmployeeId" FOREIGN KEY ("EmployeeId") REFERENCES "EmployeeProfiles" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027221048_InitialCreate') THEN
    CREATE TABLE "Orders" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OrderNumber" character varying(40) NOT NULL,
        "EmployeeId" integer NOT NULL,
        "OrderTypeId" integer NOT NULL,
        "OperationDate" date NOT NULL,
        "Status" character varying(20) NOT NULL,
        "PaymentMethodId" integer NOT NULL,
        "Subtotal" numeric(18,2) NOT NULL,
        "DeductionPercentage" numeric(5,2) NOT NULL,
        "DeductionAmount" numeric(18,2) NOT NULL,
        "NetAmount" numeric(18,2) NOT NULL,
        "Notes" character varying(1000),
        "IdempotencyKey" character varying(64),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "CreatedByUserId" integer NOT NULL,
        "CompletedAtUtc" timestamp with time zone,
        "CompletedByUserId" integer,
        "CancelledAtUtc" timestamp with time zone,
        "CancelledByUserId" integer,
        "CancellationReason" character varying(500),
        CONSTRAINT "PK_Orders" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_SalesOrder_DeductionAmount" CHECK ("DeductionAmount" >= 0 AND "DeductionAmount" <= "Subtotal"),
        CONSTRAINT "CK_SalesOrder_DeductionPercentage" CHECK ("DeductionPercentage" >= 0 AND "DeductionPercentage" <= 100),
        CONSTRAINT "CK_SalesOrder_Subtotal" CHECK ("Subtotal" > 0),
        CONSTRAINT "FK_Orders_EmployeeProfiles_EmployeeId" FOREIGN KEY ("EmployeeId") REFERENCES "EmployeeProfiles" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Orders_OrderTypes_OrderTypeId" FOREIGN KEY ("OrderTypeId") REFERENCES "OrderTypes" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Orders_PaymentMethods_PaymentMethodId" FOREIGN KEY ("PaymentMethodId") REFERENCES "PaymentMethods" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
