        CONSTRAINT "PK_DeductionRecords" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_DeductionRecords_EmployeeDeductionRates_DeductionRuleId" FOREIGN KEY ("DeductionRuleId") REFERENCES "EmployeeDeductionRates" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_DeductionRecords_EmployeeProfiles_EmployeeId" FOREIGN KEY ("EmployeeId") REFERENCES "EmployeeProfiles" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_DeductionRecords_Orders_SalesOrderId" FOREIGN KEY ("SalesOrderId") REFERENCES "Orders" ("Id") ON DELETE RESTRICT
