    CREATE UNIQUE INDEX "IX_Users_Username" ON "Users" ("Username");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027221048_InitialCreate') THEN
    PERFORM setval(
        pg_get_serial_sequence('"OrderTypes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "OrderTypes") + 1,
            nextval(pg_get_serial_sequence('"OrderTypes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Roles"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Roles") + 1,
            nextval(pg_get_serial_sequence('"Roles"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Services"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Services") + 1,
            nextval(pg_get_serial_sequence('"Services"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027221048_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261027221048_InitialCreate', '10.0.14');
    END IF;
END $EF$;
COMMIT;

